// Tipos compartidos entre la API y los componentes.
// Respuesta del endpoint POST /api/transcribe del backend FastAPI.
export interface TranscribeResponse {
  text: string;
  sessionId?: string | null;
  audioDurationMs?: number | null;
  turns: unknown[];
  topic?: string | null;
  cleaned?: string | null;
  keywords?: string[];
}

// Item del historial local de transcripciones.
export interface TranscriptItem {
  text: string;
  sessionId?: string | null;
  cleaned?: string | null;
  topic?: string | null;
  keywords?: string[];
}

// Slide generated by the LLM (plain JSON, no HTML).
export type SlideLayoutId =
  | "title_text"
  | "title_bullets"
  | "text_image"
  | "quote"
  | "hero_cover"
  | "cards_flex"
  | "split_code"
  | "split_media"
  | "separator"
  | "compare_2"
  | "checklist_flex"
  | "stats_flex"
  | "chips_flex"
  | "bullets_flex"
  | "steps_flex"
  | "definition_guided"
  | "concept_editorial"
  | "pillars_3"
  | "timeline_4"
  | "takeaway"
  | "stat_hero";

export type AudienceId =
  | "ninos"
  | "estudiantes"
  | "general"
  | "profesionales"
  | "expertos";

// Card / stat items used by flexible layouts (plain text only).
export interface SlideCard {
  title?: string;
  text?: string;
  icon?: string;
  code?: string;
  code_tipo?: string;
  code_titulo?: string;
}

export interface SlideStat {
  value?: string;
  label?: string;
}

export interface CodigoMatematica {
  tipo: "codigo" | "matematica";
  titulo: string;
  contenido: string;
}

export interface ConceptoItem {
  subtitulo?: string;
  icono?: string | null;
  texto?: string;
  codigo_matematica?: CodigoMatematica | null;
}

export interface GenerateSlideRequest {
  transcript: string;
  topic: string;
  keywords: string[];
  palette_id?: string | null;
  audience?: string;
  is_opening?: boolean | null;
}

export interface GenerateSlideResponse {
  layout: SlideLayoutId;
  title: string;
  text: string;
  bullets: string[];
  keywords: string[];
  filtered: boolean;
  kicker?: string;
  subtitle?: string;
  cards?: (SlideCard | string)[];
  stats?: (SlideStat | string)[];
  chips?: string[];
  steps?: (string | SlideCard)[];
  code?: string;
  code_tipo?: string;
  code_titulo?: string;
  codigo_matematica?: CodigoMatematica | null;
  image?: string;
  imagen_hashtag?: string;
  imagen_prompt?: string;
  explanation?: string;
  concept?: string;
  example?: string;
  takeaway?: string;
  content_type?: string;
  layout_reason?: string;
  titulo?: string;
  texto?: string;
  listado?: string[];
  conceptos?: ConceptoItem[];
  audience?: string;
  html?: string;
  palette_id?: string;
  palette?: Record<string, string>;
}

export interface SlideItem extends GenerateSlideResponse {
  id: string;
  timestamp: number;
}

// Estado visible de la sesion realtime.
export type RealtimeStatus =
  | "idle"
  | "connecting"
  | "listening"
  | "speaking"
  | "paused"
  | "error";

// Turno de transcripcion realtime, claveado por turnId (los turnos pueden solaparse).
export interface TurnState {
  turnId: string;
  text: string;
  final: boolean;
  ended: boolean;
  updatedAt: number;
  cleaned?: string | null;
  topic?: string | null;
  keywords?: string[];
}

// Eventos que el backend reenvia de Meta (realtime) mas controles propios.
export interface MetaSpeechStartEvent {
  type: "speechStart";
  turnId: string;
}

export interface MetaTranscriptEvent {
  type: "transcript";
  transcript: string;
  final?: boolean;
  turnId?: string;
  cleaned?: string | null;
  topic?: string | null;
  keywords?: string[];
}

export interface MetaSpeechEndEvent {
  type: "speechEnd";
  turnId: string;
}

export interface MetaSpeechCompleteEvent {
  type: "speechComplete";
  turnId: string;
  transcript: string;
  cleaned?: string | null;
  topic?: string | null;
  keywords?: string[];
}

export interface BridgePausedEvent {
  type: "paused";
  reason?: string;
}

export interface BridgeResumedEvent {
  type: "resumed";
  reason?: string;
}

export interface BridgeUpstreamCloseEvent {
  type: "upstream_close";
  code?: number | null;
  reason?: string;
}

export interface BridgeErrorEvent {
  type: "error";
  message: string;
}

// Eventos WS de slides async (backend realtime_proxy.py).
// Cada evento lleva turnId/seq/topicVersion obligatorios.
export interface SlidePendingEvent {
  type: "slide_pending";
  turnId: string;
  seq: number;
  topicVersion: number;
}

export interface SlideWsSlideEvent {
  type: "slide";
  turnId: string;
  seq: number;
  topicVersion: number;
  layout: SlideLayoutId;
  title: string;
  titulo?: string;
  text: string;
  texto?: string;
  bullets: string[];
  listado?: string[];
  keywords: string[];
  kicker?: string;
  subtitle?: string;
  cards?: (SlideCard | string)[];
  conceptos?: ConceptoItem[];
  stats?: (SlideStat | string)[];
  chips?: string[];
  steps?: (string | SlideCard)[];
  code?: string;
  code_tipo?: string;
  code_titulo?: string;
  codigo_matematica?: CodigoMatematica | null;
  image?: string;
  imagen_hashtag?: string;
  imagen_prompt?: string;
  explanation?: string;
  concept?: string;
  example?: string;
  takeaway?: string;
  content_type?: string;
  layout_reason?: string;
  audience?: string;
  html?: string;
  palette_id?: string;
  palette?: Record<string, string>;
}

export interface SlideFilteredEvent {
  type: "slide_filtered";
  turnId: string;
  seq: number;
  topicVersion: number;
}

// Gate decision: current slide already covers the turn, nothing to paint.
export interface SlideKeptEvent {
  type: "slide_kept";
  turnId: string;
  seq: number;
  topicVersion: number;
}

export interface SlideErrorEvent {
  type: "slide_error";
  turnId: string;
  seq: number;
  topicVersion: number;
  message?: string;
}

// Regen of a painted turn: replaces or removes the existing slide.
export interface SlideReplacedEvent {
  type: "slide_replaced";
  turnId: string;
  seq: number;
  topicVersion: number;
  layout: SlideLayoutId;
  title: string;
  titulo?: string;
  text: string;
  texto?: string;
  bullets: string[];
  listado?: string[];
  keywords: string[];
  kicker?: string;
  subtitle?: string;
  cards?: (SlideCard | string)[];
  conceptos?: ConceptoItem[];
  stats?: (SlideStat | string)[];
  chips?: string[];
  steps?: (string | SlideCard)[];
  code?: string;
  code_tipo?: string;
  code_titulo?: string;
  codigo_matematica?: CodigoMatematica | null;
  image?: string;
  imagen_hashtag?: string;
  imagen_prompt?: string;
  explanation?: string;
  concept?: string;
  example?: string;
  takeaway?: string;
  content_type?: string;
  layout_reason?: string;
  audience?: string;
  html?: string;
  palette_id?: string;
  palette?: Record<string, string>;
}

export interface SlideRemovedEvent {
  type: "slide_removed";
  turnId: string;
  seq: number;
  topicVersion: number;
}

// Progressive image: arrives after the text slide, patches it in place.
export interface SlideImageUpdatedEvent {
  type: "slide_image_updated";
  turnId: string;
  seq: number;
  topicVersion: number;
  image: string;
  html?: string;
}

export type SlideWsEvent =
  | SlidePendingEvent
  | SlideWsSlideEvent
  | SlideFilteredEvent
  | SlideKeptEvent
  | SlideErrorEvent
  | SlideReplacedEvent
  | SlideRemovedEvent
  | SlideImageUpdatedEvent;

export function isSlideWsEvent(event: ServerEvent): event is SlideWsEvent {
  return (
    event.type === "slide_pending" ||
    event.type === "slide" ||
    event.type === "slide_filtered" ||
    event.type === "slide_kept" ||
    event.type === "slide_error" ||
    event.type === "slide_replaced" ||
    event.type === "slide_removed" ||
    event.type === "slide_image_updated"
  );
}

export type ServerEvent =
  | MetaSpeechStartEvent
  | MetaTranscriptEvent
  | MetaSpeechEndEvent
  | MetaSpeechCompleteEvent
  | BridgePausedEvent
  | BridgeResumedEvent
  | BridgeUpstreamCloseEvent
  | BridgeErrorEvent
  | SlideWsEvent;
